INSERT INTO `bibliografie` (`id`, `riferimento_bibliografico`) VALUES (146,'A. d’Aniello, <i>La croce dipinta in area lucchese: riflessioni su diffusione, storia materiale e iconografia dal XII secolo a Berlinghiero</i>, in <i>Inkarnat und Signifikanz: das menschliche Abbild in der Tafelmalerei von 200 bis 1250 im Mittelmeerraum</i>, a cura di Y. Schmuhl, E.P. Wipfler, München 2017, pp. 380-391.');
INSERT INTO `bibliografie` (`id`, `riferimento_bibliografico`) VALUES (147,'F. Bianchi, <i>Appunti su due Madonne col Bambino di area pisano-lucchese del XII secolo ed una proposta iconografica riguardante un prototipo di cardellino</i>, in “Arte cristiana”, CVIII, 2020, 916, pp. 38-47. ');
INSERT INTO `bibliografie` (`id`, `riferimento_bibliografico`) VALUES (148,'M. Boskovits, S. Chiodo, <i>A Critical and Historical Corpus of Florentine Painting</i>. Suppl. <i>Mediaeval Panel Painting in Tuscany 12th to 13th century</i> 2021, pp. 48-49 cat. 4.');
